const upsertHiding = `-- name: UpsertHiding :exec
INSERT INTO combat_hiding (hider_id, observer_id, encounter_id, noticed, total, passive, created_at)
VALUES ($1, $2, $3, $4, $5, $6, $7)
ON CONFLICT (hider_id, observer_id) DO UPDATE
SET noticed = excluded.noticed, total = excluded.total, passive = excluded.passive, created_at = excluded.created_at
`

type UpsertHidingParams struct {
	HiderID     string
	ObserverID  string
	EncounterID string
	Noticed     bool
	Total       int32
	Passive     int32
	CreatedAt   time.Time
}

func (q *Queries) UpsertHiding(ctx context.Context, arg UpsertHidingParams) error {
	_, err := q.db.Exec(ctx, upsertHiding,
		arg.HiderID,
		arg.ObserverID,
		arg.EncounterID,
		arg.Noticed,
		arg.Total,
		arg.Passive,
		arg.CreatedAt,
	)
	return err
}

